import * as cdk from 'aws-cdk-lib'
import { ReprServerStack } from './repr-server-stack'

const app = new cdk.App()

const env = {
  account: process.env.CDK_DEFAULT_ACCOUNT,
  region: process.env.CDK_DEFAULT_REGION,
}

function parseCorsOrigins(
  contextKey: string,
  fallbacks: string[]
): string[] {
  const raw = app.node.tryGetContext(contextKey) as string | undefined
  if (raw === undefined || raw === null) {
    return [...fallbacks]
  }
  const list = String(raw)
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
  return list.length > 0 ? list : [...fallbacks]
}

const devCors = parseCorsOrigins('devCorsOrigins', ['http://localhost:3000'])
const prodCors = parseCorsOrigins('prodCorsOrigins', [
  'http://localhost:3000',
  'https://www.reprman.com',
  'https://reprman.com',
])

// eslint-disable-next-line no-new
new ReprServerStack(app, 'ReprServerStack-Dev', {
  env,
  stage: 'dev',
  corsAllowOrigins: devCors,
})

// eslint-disable-next-line no-new
new ReprServerStack(app, 'ReprServerStack-Prod', {
  env,
  stage: 'prod',
  corsAllowOrigins: prodCors,
})
